describe('Pagination Controls', () => {
    beforeEach(() => {
        cy.visit('/results'); // Adjust the URL to the actual page
    });

    it('should load the correct page of results when clicking the next button', () => {
        cy.get('.pagination .next').click();
        cy.url().should('include', 'page=2'); // Adjust based on actual URL structure
        cy.get('.results').should('have.length', 10); // Assuming 10 results per page
        cy.get('.results').first().should('contain', 'Expected Result on Page 2'); // Adjust based on expected content
    });

    it('should not allow navigation to a non-existent page', () => {
        cy.get('.pagination .next').click(); // Go to page 2
        cy.get('.pagination .next').click(); // Go to page 3
        cy.get('.pagination .next').click(); // Go to page 4
        cy.get('.pagination .next').click(); // Attempt to go to page 5 (non-existent)
        cy.get('.pagination .next').should('be.disabled'); // Ensure the next button is disabled
        cy.get('.results').should('have.length', 0); // Assuming no results on non-existent page
    });
});
